package org.eclipse.rdf4j.query.algebra.evaluation.optimizer;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.Dataset;
import org.eclipse.rdf4j.query.algebra.And;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.LeftJoin;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.ValueExpr;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryOptimizer;
import org.eclipse.rdf4j.query.algebra.evaluation.util.QueryEvaluationUtility;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractSimpleQueryModelVisitor;
import org.eclipse.rdf4j.query.algebra.helpers.QueryAlgebraBindingAnalysis;

/**
 * Splits conjunctive constraints into seperate constraints.
 *
 * @author Arjohn Kampman
 */
public class ConjunctiveConstraintSplitterOptimizer implements QueryOptimizer {

	@Override
	public void optimize(TupleExpr tupleExpr, Dataset dataset, BindingSet bindings) {
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(tupleExpr, bindings);
		tupleExpr.visit(new ConstraintVisitor(analysis));
	}

	private static class ConstraintVisitor extends AbstractSimpleQueryModelVisitor<RuntimeException> {
		private record RelocatedConstraint(ValueExpr condition, Set<String> required) {
		}

		private final QueryAlgebraBindingAnalysis analysis;

		ConstraintVisitor(QueryAlgebraBindingAnalysis analysis) {
			super(false);
			this.analysis = analysis;
		}

		@Override
		public void meet(Filter filter) {
			super.meet(filter);
			if (!QueryEvaluationUtility.isRepeatable(filter.getCondition())) {
				return;
			}

			List<ValueExpr> conjunctiveConstraints = new ArrayList<>(16);
			getConjunctiveConstraints(filter.getCondition(), conjunctiveConstraints);
			if (conjunctiveConstraints.size() < 2
					|| !conjunctiveConstraints.stream().allMatch(AlgebraEvaluationSafety::isRepeatable)) {
				return;
			}

			TupleExpr filterArg = filter.getArg();

			for (int i = 0; i < conjunctiveConstraints.size() - 1; i++) {
				Filter split = new Filter(filterArg, conjunctiveConstraints.get(i).clone());
				split.setRequiredInputBindingNames(filter.getRequiredInputBindingNames());
				filterArg = split;
			}

			filter.setCondition(conjunctiveConstraints.getLast().clone());
			filter.setArg(filterArg);
			analysis.invalidate();
		}

		@Override
		public void meet(LeftJoin node) {
			super.meet(node);

			if (node.getCondition() != null && QueryEvaluationUtility.isRepeatable(node.getCondition())) {
				List<ValueExpr> conjunctiveConstraints = new ArrayList<>();
				getConjunctiveConstraints(node.getCondition(), conjunctiveConstraints);
				if (!conjunctiveConstraints.stream().allMatch(AlgebraEvaluationSafety::isRepeatable)) {
					return;
				}

				TupleExpr arg = node.getRightArg();
				List<RelocatedConstraint> relocatedConstraints = new ArrayList<>();
				ValueExpr condition = null;
				QueryAlgebraBindingAnalysis.ReadOnlyContext conditionInput = analysis.contextAt(node.getCondition());
				QueryAlgebraBindingAnalysis.ReadOnlyContext rightInput = analysis.contextAt(arg);
				QueryAlgebraBindingAnalysis.OutputFacts leftFacts = analysis.outputFacts(node.getLeftArg(),
						analysis.contextAt(node.getLeftArg()));
				QueryAlgebraBindingAnalysis.OutputFacts rightFacts = analysis.outputFacts(arg, rightInput);

				for (ValueExpr constraint : conjunctiveConstraints) {
					QueryAlgebraBindingAnalysis.Dependencies dependencies = analysis.dependencies(constraint,
							conditionInput);
					Set<String> required = new HashSet<>(dependencies.directReferences());
					required.addAll(dependencies.correlatedInputs());
					required.retainAll(leftFacts.guaranteedOutputs());
					required.removeAll(rightFacts.guaranteedOutputs());
					required.removeAll(analysis.contextAt(node).guaranteedNames());
					if (isWithinBindingScope(leftFacts, rightFacts, rightInput, conditionInput, dependencies)
							&& (required.isEmpty() || analysis.canReceiveSiblingBindings(arg,
									node.getLeftArg().getBindingNames(), analysis.contextAt(node)))) {
						relocatedConstraints.add(new RelocatedConstraint(constraint, Set.copyOf(required)));
					} else if (condition == null) {
						condition = constraint.clone();
					} else {
						condition = new And(condition, constraint.clone());
					}
				}
				if (condition != null && analysis.leftJoinConditionUsesLeftFrame(node) != analysis
						.leftJoinConditionUsesLeftFrame(node, condition)) {
					// Removing a right-observing conjunct must not switch the remaining condition from the
					// matched frame to old left values. Keep the original gate as one semantic unit.
					return;
				}
				for (RelocatedConstraint constraint : relocatedConstraints) {
					Filter relocated = new Filter(arg, constraint.condition().clone());
					relocated.setRequiredInputBindingNames(constraint.required());
					arg = relocated;
				}

				node.setCondition(condition);
				node.setRightArg(arg);
				analysis.invalidate();
			}
		}

		protected void getConjunctiveConstraints(ValueExpr valueExpr, List<ValueExpr> conjunctiveConstraints) {
			if (valueExpr instanceof And and) {
				getConjunctiveConstraints(and.getLeftArg(), conjunctiveConstraints);
				getConjunctiveConstraints(and.getRightArg(), conjunctiveConstraints);
			} else {
				conjunctiveConstraints.add(valueExpr);
			}
		}

		private boolean isWithinBindingScope(QueryAlgebraBindingAnalysis.OutputFacts leftFacts,
				QueryAlgebraBindingAnalysis.OutputFacts rightFacts,
				QueryAlgebraBindingAnalysis.ReadOnlyContext rightInput,
				QueryAlgebraBindingAnalysis.ReadOnlyContext conditionInput,
				QueryAlgebraBindingAnalysis.Dependencies dependencies) {
			if (!rightFacts.possibleOutputsKnown() || !rightFacts.guaranteedOutputsKnown()
					|| !leftFacts.possibleOutputsKnown() || !leftFacts.guaranteedOutputsKnown()) {
				return false;
			}
			Set<String> references = new HashSet<>(dependencies.directReferences());
			references.addAll(dependencies.correlatedInputs());
			if (!analysis.bindingsStableAt(references, conditionInput, rightInput, rightFacts, null)) {
				return false;
			}
			for (String name : references) {
				boolean leftMayBind = leftFacts.possibleOutputs().contains(name)
						|| leftFacts.retainedInputNames().contains(name);
				if (rightFacts.overwrittenInputNames().contains(name)
						&& (leftMayBind || rightInput.maybeBoundNames().contains(name))) {
					// The original OPTIONAL condition can observe the left row's value before an RHS Extension replaces
					// it.
					return false;
				}
				boolean rightCanSeeName = rightFacts.possibleOutputs().contains(name)
						|| rightFacts.retainedInputNames().contains(name)
								&& rightInput.maybeBoundNames().contains(name);
				if (!rightCanSeeName) {
					return false;
				}
			}
			return true;
		}
	}
}
